def pick(unit=None, lesson=None, count=10):
    items = [q for q in QUESTIONS if (unit is None or q[0]==unit) and (lesson is None or q[1]==lesson)]
    random.shuffle(items)
    return items[:min(count, len(items))]

async def start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    msg = update.effective_message
    thread = getattr(msg, "message_thread_id", None)
    await msg.reply_text(
        "🌟 أهلًا بك في بنك أسئلة المهارات الرقمية\n"
        "رابع ابتدائي\n\n"
        "الأوامر:\n"
        "/unit1 — أسئلة الوحدة الأولى\n"
        "/unit2 — أسئلة الوحدة الثانية\n"
        "/mixed — اختبار شامل من الوحدتين\n"
        "/lessons — قائمة الدروس\n"
        "/id — معلومات المجموعة والموضوع\n\n"
        "إعداد المعلمة رحاب الزهراني"
    )

async def ids(update: Update, context: ContextTypes.DEFAULT_TYPE):
    m=update.effective_message
    await m.reply_text(f"chat_id: {update.effective_chat.id}\nmessage_thread_id: {getattr(m,'message_thread_id',None)}")

async def lessons(update: Update, context: ContextTypes.DEFAULT_TYPE):
    await update.effective_message.reply_text(
        "📚 الدروس المتاحة\n\n"
        "الوحدة الأولى: تعلم الأساسيات\n"
        "1️⃣ الحاسب /l11\n2️⃣ سطح المكتب /l12\n3️⃣ إعدادات جهاز الحاسب /l13\n\n"
        "الوحدة الثانية: العمل على النص\n"
        "1️⃣ لوحة المفاتيح /l21\n2️⃣ تحرير النص /l22\n3️⃣ تنسيق النص /l23\n4️⃣ تنسيق الفقرة /l24"
    )

async def send_quiz(update, context, unit=None, lesson=None, count=10):
    m=update.effective_message
    qs=pick(unit, lesson, count)
    if not qs:
        await m.reply_text("لا توجد أسئلة في هذا القسم بعد.")
        return
    await m.reply_text(f"🧠 سيبدأ الآن اختبار من {len(qs)} أسئلة\nاختاري الإجابة الصحيحة لكل سؤال.")
    for unit_name, lesson_name, q, options, answer, explanation in qs:
        # shuffle options while preserving correct answer
        correct = options[answer]
        shuffled = options[:]
        random.shuffle(shuffled)
        correct_id = shuffled.index(correct)
        await context.bot.send_poll(
            chat_id=update.effective_chat.id,
            message_thread_id=getattr(m, "message_thread_id", None),
            question=q,
            options=shuffled,
            type=PollType.QUIZ,
            correct_option_id=correct_id,
            explanation=explanation,
            is_anonymous=False
        )

async def unit1(update, context):
    await send_quiz(update, context, unit="الوحدة الأولى: تعلم الأساسيات", count=15)
async def unit2(update, context):
    await send_quiz(update, context, unit="الوحدة الثانية: العمل على النص", count=15)
async def mixed(update, context):
    await send_quiz(update, context, count=20)

async def l11(u,c): await send_quiz(u,c,lesson="الدرس الأول: الحاسب",count=10)
async def l12(u,c): await send_quiz(u,c,lesson="الدرس الثاني: سطح المكتب",count=12)
async def l13(u,c): await send_quiz(u,c,lesson="الدرس الثالث: إعدادات جهاز الحاسب",count=10)
async def l21(u,c): await send_quiz(u,c,lesson="الدرس الأول: لوحة المفاتيح",count=10)
async def l22(u,c): await send_quiz(u,c,lesson="الدرس الثاني: تحرير النص",count=10)
async def l23(u,c): await send_quiz(u,c,lesson="الدرس الثالث: تنسيق النص",count=12)
async def l24(u,c): await send_quiz(u,c,lesson="الدرس الرابع: تنسيق الفقرة",count=12)

def main():
    logging.basicConfig(level=logging.INFO)
    app=Application.builder().token(TOKEN).build()
    handlers=[
        ("start",start),("id",ids),("lessons",lessons),
        ("unit1",unit1),("unit2",unit2),("mixed",mixed),
        ("l11",l11),("l12",l12),("l13",l13),
        ("l21",l21),("l22",l22),("l23",l23),("l24",l24)
    ]
    for name,fn in handlers:
        app.add_handler(CommandHandler(name,fn))
    print("DigitalSkillsRahabBot is running...")
    app.run_polling(allowed_updates=Update.ALL_TYPES)

if __name__=="__main__":
    main()
